func Enrich(ids []int64, repo Repository) []Item {
	var results []Item
	for _, id := range ids {
		item := repo.Load(id)
		if !item.Active {
			continue
		}
		if item.Owner == nil || !item.Owner.Enabled {
			continue
		}
		results = append(results, item)
	}
	return results
}

